const { useState, useEffect, useRef } = React;

const NOTE_NAMES = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B'];
const WHITE_KEYS = [
  { name: 'C', semitone: 0, label: '도' },
  { name: 'D', semitone: 2, label: '레' },
  { name: 'E', semitone: 4, label: '미' },
  { name: 'F', semitone: 5, label: '파' },
  { name: 'G', semitone: 7, label: '솔' },
  { name: 'A', semitone: 9, label: '라' },
  { name: 'B', semitone: 11, label: '시' },
];
const BLACK_KEYS = [
  { name: 'C#', semitone: 1, after: 0 },
  { name: 'D#', semitone: 3, after: 1 },
  { name: 'F#', semitone: 6, after: 3 },
  { name: 'G#', semitone: 8, after: 4 },
  { name: 'A#', semitone: 10, after: 5 },
];

// 음 이름 -> 주파수 (A4 = 440Hz)
function noteToFreq(semitone, octave) {
  const n = semitone + (octave - 4) * 12 - 9; // A4 기준
  return Math.round(440 * Math.pow(2, n / 12));
}

function App() {
  const [octave, setOctave] = useState(4);
  const [volume, setVolume] = useState(70);
  const [activeNote, setActiveNote] = useState(null);
  const [theremin, setTheremin] = useState(false);
  const [thereminFreq, setThereminFreq] = useState(0);
  const [log, setLog] = useState([]);

  const octaveRef = useRef(4);
  const volumeRef = useRef(70);
  const thereminRef = useRef(false);
  const lastFreqRef = useRef(0);
  const lastSetRef = useRef(0);

  useEffect(() => { octaveRef.current = octave; }, [octave]);
  useEffect(() => { volumeRef.current = volume; }, [volume]);
  useEffect(() => { thereminRef.current = theremin; }, [theremin]);

  // 다이얼로 옥타브 조절 (turn 각도 -> 옥타브 2~6)
  useEffect(() => {
    const offDial = MODI.onValue('dial', 1, 'turn', (turn) => {
      const oct = 2 + Math.round((Math.max(0, Math.min(360, turn || 0)) / 360) * 4);
      if (oct !== octaveRef.current) {
        octaveRef.current = oct;
        setOctave(oct);
      }
    }, { pollMs: 60 });
    return () => { offDial(); };
  }, []);

  // 테레민: 거리센서(cm) -> 주파수
  useEffect(() => {
    const offTof = MODI.onValue('tof', 1, 'distance', (dist) => {
      if (!thereminRef.current) return;
      const d = dist || 0;
      if (d <= 0 || d > 40) {
        if (lastFreqRef.current !== 0) {
          lastFreqRef.current = 0;
          MODI.speaker(1).stop();
        }
        return;
      }
      // 2cm~40cm -> 200Hz~1200Hz
      const clamped = Math.max(2, Math.min(40, d));
      const freq = Math.round(200 + (1 - (clamped - 2) / 38) * 1000);
      lastFreqRef.current = freq;
      MODI.speaker(1).playTone(freq, volumeRef.current);
      const now = performance.now();
      if (now - lastSetRef.current > 120) {
        lastSetRef.current = now;
        setThereminFreq(freq);
      }
    }, { pollMs: 40 });
    return () => { offTof(); };
  }, []);

  // 테레민 켜고 끌 때 소리 정리
  useEffect(() => {
    if (!theremin) {
      MODI.speaker(1).stop();
      lastFreqRef.current = 0;
      setThereminFreq(0);
    }
  }, [theremin]);

  const playKey = (semitone, name) => {
    if (theremin) return;
    const freq = noteToFreq(semitone, octave);
    MODI.speaker(1).playTone(freq, volume);
    setActiveNote(name + octave);
    setLog((prev) => [`${name}${octave}  ${freq}Hz`, ...prev].slice(0, 8));
  };

  const stopKey = () => {
    if (theremin) return;
    MODI.speaker(1).stop();
    setActiveNote(null);
  };

  const reset = () => {
    MODI.speaker(1).stop();
    setOctave(4);
    setVolume(70);
    setActiveNote(null);
    setTheremin(false);
    setThereminFreq(0);
    setLog([]);
    lastFreqRef.current = 0;
  };

  return (
    <div className="h-screen flex flex-col bg-gradient-to-br from-slate-900 via-indigo-950 to-slate-900 text-white">
      {/* 헤더 */}
      <div className="flex-shrink-0 px-8 py-5 flex items-center justify-between border-b border-white/10">
        <div>
          <h1 className="text-2xl font-bold tracking-tight">MODI 신디사이저</h1>
          <p className="text-sm text-indigo-300/70">모디 스피커로 연주하는 음악 웹</p>
        </div>
        <button
          onClick={reset}
          className="px-4 py-2 rounded-xl bg-white/10 hover:bg-white/20 text-sm font-medium transition-colors"
        >
          초기화
        </button>
      </div>

      {/* 본문 */}
      <div className="flex-1 min-h-0 flex flex-col p-8 gap-6">
        {/* 컨트롤 패널 */}
        <div className="flex-shrink-0 grid grid-cols-3 gap-4">
          <div className="rounded-2xl bg-white/5 border border-white/10 p-5">
            <div className="text-xs uppercase tracking-wider text-indigo-300/60 mb-1">옥타브 (다이얼)</div>
            <div className="text-4xl font-bold text-indigo-300">{octave}</div>
            <div className="mt-3 flex gap-2">
              <button onClick={() => setOctave((o) => Math.max(2, o - 1))} className="flex-1 py-1.5 rounded-lg bg-white/10 hover:bg-white/20 text-sm">-</button>
              <button onClick={() => setOctave((o) => Math.min(6, o + 1))} className="flex-1 py-1.5 rounded-lg bg-white/10 hover:bg-white/20 text-sm">+</button>
            </div>
          </div>

          <div className="rounded-2xl bg-white/5 border border-white/10 p-5">
            <div className="text-xs uppercase tracking-wider text-indigo-300/60 mb-1">음량</div>
            <div className="text-4xl font-bold text-pink-300">{volume}</div>
            <input
              type="range" min={0} max={100} value={volume}
              onChange={(e) => setVolume(Number(e.target.value))}
              className="w-full mt-3 accent-pink-400"
            />
          </div>

          <div className="rounded-2xl bg-white/5 border border-white/10 p-5 flex flex-col">
            <div className="text-xs uppercase tracking-wider text-indigo-300/60 mb-1">테레민 모드 (거리센서)</div>
            <button
              onClick={() => setTheremin((t) => !t)}
              className={`mt-1 py-2 rounded-xl font-semibold transition-colors ${theremin ? 'bg-emerald-500 text-white' : 'bg-white/10 hover:bg-white/20'}`}
            >
              {theremin ? `연주중  ${thereminFreq}Hz` : '켜기'}
            </button>
            <div className="mt-2 text-xs text-indigo-300/50">손을 거리센서 가까이/멀리</div>
          </div>
        </div>

        {/* 현재 음 표시 */}
        <div className="flex-shrink-0 flex items-center justify-center">
          <div className="text-lg font-medium text-indigo-200/80">
            {theremin ? (thereminFreq > 0 ? `테레민 ♪ ${thereminFreq}Hz` : '거리센서에 손을 대보세요') : (activeNote ? `연주중 ♪ ${activeNote}` : '건반을 눌러 연주하세요')}
          </div>
        </div>

        {/* 피아노 건반 */}
        <div className="flex-1 min-h-0 flex items-center justify-center">
          <div className={`relative w-full max-w-3xl h-full max-h-72 select-none ${theremin ? 'opacity-30 pointer-events-none' : ''}`}>
            {/* 흰 건반 */}
            <div className="absolute inset-0 flex gap-1.5">
              {WHITE_KEYS.map((key) => {
                const id = key.name + octave;
                const isActive = activeNote === id;
                return (
                  <button
                    key={key.name}
                    onMouseDown={() => playKey(key.semitone, key.name)}
                    onMouseUp={stopKey}
                    onMouseLeave={() => { if (activeNote === id) stopKey(); }}
                    onTouchStart={(e) => { e.preventDefault(); playKey(key.semitone, key.name); }}
                    onTouchEnd={stopKey}
                    className={`flex-1 rounded-b-xl flex items-end justify-center pb-4 font-semibold transition-all ${isActive ? 'bg-indigo-400 text-white shadow-inner translate-y-0.5' : 'bg-white text-slate-700 hover:bg-indigo-50'}`}
                  >
                    <span className="text-sm">{key.label}</span>
                  </button>
                );
              })}
            </div>
            {/* 검은 건반 */}
            <div className="absolute inset-0 pointer-events-none">
              {BLACK_KEYS.map((key) => {
                const id = key.name + octave;
                const isActive = activeNote === id;
                const leftPct = ((key.after + 1) / 7) * 100;
                return (
                  <button
                    key={key.name}
                    onMouseDown={() => playKey(key.semitone, key.name)}
                    onMouseUp={stopKey}
                    onMouseLeave={() => { if (activeNote === id) stopKey(); }}
                    onTouchStart={(e) => { e.preventDefault(); playKey(key.semitone, key.name); }}
                    onTouchEnd={stopKey}
                    style={{ left: `calc(${leftPct}% - 4%)`, width: '8%' }}
                    className={`absolute top-0 h-3/5 rounded-b-lg pointer-events-auto transition-all ${isActive ? 'bg-indigo-500' : 'bg-slate-900 hover:bg-slate-700'} border-2 border-slate-800 shadow-lg`}
                  />
                );
              })}
            </div>
          </div>
        </div>

        {/* 연주 기록 */}
        <div className="flex-shrink-0 h-10 flex items-center gap-2 overflow-hidden">
          <span className="text-xs text-indigo-300/50 flex-shrink-0">기록</span>
          {log.map((item, i) => (
            <span key={i} className="px-3 py-1 rounded-full bg-white/5 border border-white/10 text-xs text-indigo-200/70 whitespace-nowrap">{item}</span>
          ))}
        </div>
      </div>
    </div>
  );
}

export default App;
